package dev.thillainirmal.contextbridge.config;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.List;
@Configuration
public class SecurityConfig {
 @Bean SecurityFilterChain security(HttpSecurity http,@Value("${contextbridge.api-key}")String key)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/","/index.html","/*.js","/*.css").permitAll().anyRequest().authenticated()).addFilterBefore(new BearerFilter(key),UsernamePasswordAuthenticationFilter.class).build();}
 static class BearerFilter extends OncePerRequestFilter {private final byte[] expected;BearerFilter(String key){if(key.length()<24)throw new IllegalArgumentException("CONTEXTBRIDGE_API_KEY must contain at least 24 characters");expected=key.getBytes(StandardCharsets.UTF_8);}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&MessageDigest.isEqual(expected,h.substring(7).getBytes(StandardCharsets.UTF_8)))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("mcp-client",null,List.of()));chain.doFilter(req,res);}}
}
